import { styled, Text } from '@tamagui/web';
import type { ReactNode } from 'react';

import { ariaAndDataAttributes } from '../../helpers/ariaAndDataAttributes';
import { customProperties } from '../../helpers/customProperties';
import { pickWebPressHandlers } from '../../helpers/pickAttributes';
import type { SpanActionAttributes } from '../../types/ElementAttributes';

export type MessageEmojiBaseProps = {
	/** The emoji sprite's class name, added to the element as is. */
	name: string;
	image?: string;
	children?: ReactNode;
} & SpanActionAttributes;

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

const messageEmojiFrame = {
	whiteSpace: 'inherit',
	wordWrap: 'inherit',
	render: 'span',
	display: 'inline-flex',
	overflow: 'visible',
	justifyContent: 'center',
	marginInline: '2px',
	verticalAlign: 'top',
	width: 'var(--emoji-size, 1.25rem)',
	height: 'var(--emoji-size, 1.25rem)',
	fontSize: 'var(--emoji-size, 1.25rem)',
	lineHeight: 'var(--emoji-size, 1.25rem)',
	backgroundImage: 'var(--rcx-message-emoji-image)',
} as const;

const messageEmojiKinds = {
	message: {
		backgroundSize: 'contain',
	},
	reaction: {},
	thread: {
		backgroundSize: 'contain',
		verticalAlign: 'middle',
	},
} as const;

// end of generated

// Declared where it renders: zero-runtime only erases a `styled()` whose every use is in its own module
const MessageEmojiFrame = styled(Text, {
	...messageEmojiFrame,
	variants: { kind: messageEmojiKinds },
});

const MessageEmojiBase = (props: MessageEmojiBaseProps & { kind: 'message' | 'reaction' | 'thread' }) => (
	<MessageEmojiFrame
		kind={props.kind}
		className={`${props.className || ''} ${props.name}`}
		render={
			<span
				{...ariaAndDataAttributes(props)}
				{...pickWebPressHandlers(props)}
				{...customProperties({ '--rcx-message-emoji-image': props.image?.length ? props.image : undefined })}
				ref={props.ref}
				id={props.id}
				title={props.title}
				role={props.role}
				tabIndex={props.tabIndex}
			/>
		}
	>
		{props.children}
	</MessageEmojiFrame>
);

export default MessageEmojiBase;
